// src/components/Questionnaire.js
import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import "./Questionnaire.css";

const rangeOptions = [
  "0-10k", "10k-25k", "25k-50k", "50k-75k", "75k-100k", "100k+"
];

function Questionnaire({ updateData }) {
  const navigate = useNavigate();
  const [answers, setAnswers] = useState({
    incomeRange: "",
    spendingRange: "",
    savingRange: ""
  });

  const handleChange = (e) => setAnswers({ ...answers, [e.target.name]: e.target.value });

  const handleContinue = () => {
    if (!answers.incomeRange || !answers.spendingRange || !answers.savingRange) {
      alert("Please select all ranges");
      return;
    }
    updateData({ questionnaire: answers });
    navigate("/spending");
  };

  return (
    <div className="questionnaire-container">
      <div className="questionnaire-card">
        <h2 className="questionnaire-title">Questionnaire</h2>

        <div className="form-group">
          <label className="form-label">Income Range</label>
          <select className="form-select" name="incomeRange" value={answers.incomeRange} onChange={handleChange}>
            <option value="">Select Income Range</option>
            {rangeOptions.map(opt => <option key={opt} value={opt}>{opt}</option>)}
          </select>
        </div>

        <div className="form-group">
          <label className="form-label">Spending Range</label>
          <select className="form-select" name="spendingRange" value={answers.spendingRange} onChange={handleChange}>
            <option value="">Select Spending Range</option>
            {rangeOptions.map(opt => <option key={opt} value={opt}>{opt}</option>)}
          </select>
        </div>

        <div className="form-group">
          <label className="form-label">Saving Range</label>
          <select className="form-select" name="savingRange" value={answers.savingRange} onChange={handleChange}>
            <option value="">Select Saving Range</option>
            {rangeOptions.map(opt => <option key={opt} value={opt}>{opt}</option>)}
          </select>
        </div>

        <button className="next-button" onClick={handleContinue}>Continue</button>
      </div>
    </div>
  );
}

export default Questionnaire;
